//! Bitmap fonts: the evo fonts, the evo framework's text face (Noto Sans
//! merged for every script music metadata comes in), rasterised once, on
//! the workstation, into tables the daemon carries; no font parser or
//! rasteriser runs on the player. One bit per pixel, each glyph cropped to
//! its ink.
//!
//! The tables are generated by `just_oled-journal/tools/fontgen.py` and
//! are Font Software under the SIL Open Font License 1.1 (see
//! `fonts/OFL-evo.txt`), distinct from the code's MIT licence.

mod evo_12;
mod evo_16;
mod evo_24;

/// A glyph's ink and metrics: `left` and `top` place the ink's box in the
/// line's cell, the pen moves on by `advance`.
#[derive(Clone, Copy, Debug)]
pub struct Glyph {
    pub ch: u32,
    pub left: i8,
    pub top: i8,
    pub width: u8,
    pub height: u8,
    pub advance: u8,
    /// Into the font's bitmap: `height` rows of `width.div_ceil(8)` bytes, MSB left.
    pub offset: u32,
}

#[derive(Clone, Copy, Debug)]
pub struct Font {
    pub name: &'static str,
    /// Ascent plus descent: the cell height, and the distance between lines.
    pub line_height: u8,
    /// Baseline from the top of the cell.
    pub ascent: u8,
    /// Sorted by `ch`.
    pub glyphs: &'static [Glyph],
    pub bitmap: &'static [u8],
}

/// 15-pixel lines: two on a 32-pixel panel.
pub const SMALL: &Font = &evo_12::FONT;
/// 20-pixel lines: three on a 64-pixel panel.
pub const MEDIUM: &Font = &evo_16::FONT;
/// 30-pixel lines: titles on a 128-pixel panel.
pub const LARGE: &Font = &evo_24::FONT;

impl Font {
    /// The glyph for `ch`, or `None` when the font has no such ink.
    pub fn glyph(&self, ch: char) -> Option<&Glyph> {
        let cp = ch as u32;
        self.glyphs
            .binary_search_by_key(&cp, |g| g.ch)
            .ok()
            .map(|i| &self.glyphs[i])
    }

    /// The glyph for `ch`, else the one drawn in its place: the
    /// replacement character's, else a question mark's.
    pub fn glyph_or_mark(&self, ch: char) -> Option<&Glyph> {
        self.glyph(ch)
            .or_else(|| self.glyph('\u{FFFD}'))
            .or_else(|| self.glyph('?'))
    }

    /// The pen's travel over `text`, in pixels.
    pub fn width(&self, text: &str) -> i32 {
        text.chars()
            .filter_map(|c| self.glyph_or_mark(c))
            .map(|g| g.advance as i32)
            .sum()
    }

    /// Whether `(x, y)` inside the glyph's ink box is lit.
    pub fn lit(&self, g: &Glyph, x: u32, y: u32) -> bool {
        let row_bytes = (g.width as u32).div_ceil(8);
        let i = g.offset + y * row_bytes + x / 8;
        self.bitmap[i as usize] & (0x80 >> (x % 8)) != 0
    }

    /// As much of `text` as fits in `max_width`, an ellipsis closing it
    /// when something had to go. Whole characters only.
    pub fn fit<'a>(&self, text: &'a str, max_width: i32) -> std::borrow::Cow<'a, str> {
        if self.width(text) <= max_width {
            return std::borrow::Cow::Borrowed(text);
        }
        let ellipsis = if self.glyph('\u{2026}').is_some() {
            "\u{2026}"
        } else {
            "..."
        };
        let room = max_width - self.width(ellipsis);
        let mut used = 0;
        let mut end = 0;
        for (i, c) in text.char_indices() {
            let w = self.glyph_or_mark(c).map_or(0, |g| g.advance as i32);
            if used + w > room {
                break;
            }
            used += w;
            end = i + c.len_utf8();
        }
        let mut out = text[..end].trim_end().to_string();
        out.push_str(ellipsis);
        std::borrow::Cow::Owned(out)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_tables_are_sorted_and_within_their_bitmaps() {
        for font in [SMALL, MEDIUM, LARGE] {
            assert!(
                font.glyphs.windows(2).all(|w| w[0].ch < w[1].ch),
                "{}",
                font.name
            );
            for g in font.glyphs {
                let rows = (g.width as usize).div_ceil(8);
                assert!(
                    g.offset as usize + rows * g.height as usize <= font.bitmap.len(),
                    "{} U+{:04X}",
                    font.name,
                    g.ch
                );
            }
            assert!(font.ascent < font.line_height);
        }
        assert_eq!(SMALL.line_height, 15);
        assert_eq!(MEDIUM.line_height, 20);
        assert_eq!(LARGE.line_height, 30);
    }

    #[test]
    fn glyphs_are_found_and_the_missing_ones_fall_back() {
        let a = MEDIUM.glyph('A').expect("A");
        assert!(a.width > 0 && a.height > 0 && a.advance > 0);
        assert!(MEDIUM.glyph('Ж').is_some());
        assert!(MEDIUM.glyph('Ω').is_some());
        assert!(MEDIUM.glyph('€').is_some());
        assert!(MEDIUM.glyph('…').is_some());
        // Not in the font: the music note; falls back on a mark.
        assert!(MEDIUM.glyph('\u{266A}').is_none());
        assert!(MEDIUM.glyph_or_mark('\u{266A}').is_some());
        let space = MEDIUM.glyph(' ').expect("space");
        assert_eq!(space.width, 0);
        assert!(space.advance > 0);
        // Something is lit in a capital's top row.
        assert!((0..a.width as u32).any(|x| MEDIUM.lit(a, x, 0)));
    }

    #[test]
    fn text_is_measured_and_fitted() {
        let w = MEDIUM.width("Hello");
        assert!(w > 30 && w < 60, "{w}");
        assert_eq!(MEDIUM.fit("Hello", 128), "Hello");
        let cut = MEDIUM.fit("A very long title that cannot fit on a small panel", 128);
        assert!(cut.ends_with('…'), "{cut}");
        assert!(MEDIUM.width(&cut) <= 128, "{cut}");
        assert!(cut.len() > 1);
    }
}
